import numpy as np
import copy
def _fp(a):
    """Scale-aware fingerprint; every component carries O(1) weight."""
    a = np.asarray(a)
    if np.iscomplexobj(a):
        a = np.concatenate([np.real(a).ravel(), np.imag(a).ravel()])
    a = np.asarray(a, dtype=float).ravel()
    w = 1.0 + (np.arange(a.size) % 97) / 97.0
    return float(np.sum(w * a / (1.0 + np.abs(a))))
def _v(fn):
    try:
        out = fn()
        if isinstance(out, (tuple, list)):
            return float(sum(_fp(x) * (i + 1) for i, x in enumerate(out)))
        return _fp(out)
    except ValueError:
        return -1.2345e6
    except Exception:
        return -9.8765e6
SD = [90.0, 110.0, 70.0]
SA = [90.0, 110.0, 70.0]
TAU = [40.0, 180.0, 3000.0]
TG = np.arange(0.0, 220.0 + 0.5, 1.0)
assert np.allclose(_v(lambda: dephasing_lineshape(copy.deepcopy(TG), copy.deepcopy(SD), copy.deepcopy(SA), copy.deepcopy(TAU), 1000.0)), target)

